    t[50730] = { name = "Глорензельг, Високий Клинок Срібної Руки", fen = "Paragon of the Light, lead our armies against the coming darkness.", fua = "Взірцю Світла, веди наші війська проти прийдешньої темряви." }
    t[50731] = { name = "Аркус, Великий Посох Антонідаса", fen = "Six ornate runes encircle the head of the staff.", fua = "Шість вишуканих рун оперізують навершя посоха." }
    t[50732] = { name = "Кровоплин, Клинок Агонії Кел'Тузада", fen = "This world will burn.", fua = "Цей світ згорить." }
    t[50733] = { name = "Фал'інраш, Захисник Квел'Таласа", fen = "Thalas'din belore.", fua = "Талас'дін белоре." }
    t[50734] = { name = "Королівський Скіпетр Теренаса II", fen = "Though broken and corrupt, you can still make out the royal seal of Lordaeron.", fua = "Хоч він зламаний і споганений, ти все ще можеш розрізнити королівську печатку Лордерона." }
    t[50735] = { name = "Узи Клятви, Тягар Генерала Лісничих", fen = "A grotesque skull now rests atop the blade. Etched in blood across the axe head is one word repeated ten times: SUFFER.", fua = "Гротескний череп тепер вінчає клинок. Кров'ю на лезі сокири викарбувано одне слово, повторене десять разів: СТРАЖДАЙ." }
    t[50736] = { name = "Падіння Небес, Кріс Тисячі Брехень", fen = "A lying tongue hates those it crushes, but a flattering mouth works ruin.", fua = "Брехливий язик ненавидить тих, кого нищить, а улеслива вуста сіють руїну." }
    t[50737] = { name = "Поклик Сум'яття, Клинок Королів Лордерона", fen = "Let our enemies know that havoc calls and that with its song comes their end.", fua = "Хай вороги наші знають, що сум'яття кличе, і що з його піснею приходить їхній кінець." }
    t[50738] = { name = "Мітріос, Спадок Бронзбірда", fen = "Beneath the Scourge corruption you are able to make out a faint inscription: ...cry with me in the unified voice that will resonate to the throne of the Lich King himself! FOR THE ALLIANCE AND FOR KHAZ MODAN!", fua = "Під спотворенням Погибелі ти можеш розгледіти ледь помітний напис: ...кричіть зі мною єдиним голосом, що залунає аж до трону самого Короля-Ліча! ЗА АЛЬЯНС І ЗА КХАЗ МОДАН!" }
